SELECT


WHERE a.deleted = 0 AND a.status = 1
AND a.id <> #{id}
AND a.category_id = #{categoryId}
ORDER BY a.view_count DESC, a.id DESC
LIMIT #{limit}

SELECT a.id, a.title, a.cover, a.summary, a.author, a.tags, a.category_id AS categoryId, a.view_count AS viewCount, a.like_count AS likeCount, a.comment_count AS commentCount, a.is_top AS isTop, a.status, a.create_time AS createTime, a.update_time AS updateTime, c.name AS categoryName FROM article a LEFT JOIN category c ON c.id = a.category_id WHERE a.deleted = 0
AND a.id IN
#{aid}
AND a.category_id = #{q.categoryId}
AND a.status = #{q.status}
AND a.is_top = #{q.isTop}
AND ( a.title LIKE CONCAT('%', #{q.keyword}, '%') OR a.summary LIKE CONCAT('%', #{q.keyword}, '%') OR a.author LIKE CONCAT('%', #{q.keyword}, '%') )
AND a.create_time >= #{q.startTime}
AND a.create_time <= #{q.endTime}
ORDER BY a.view_count DESC, a.id DESC
ORDER BY a.like_count DESC, a.id DESC
ORDER BY a.comment_count DESC, a.id DESC
ORDER BY a.is_top DESC, a.create_time DESC, a.id DESC

SELECT


WHERE a.deleted = 0 AND a.status = 1

    AND a.id NOT IN

        #{eid}


ORDER BY a.view_count DESC, a.id DESC
LIMIT #{limit}
